import React, { useState, useEffect, useCallback } from 'react';

const API = 'http://localhost:5000/api';

export default function AdminRentals() {
  const [rentals, setRentals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all'); // all, active, returned, late
  const [msg, setMsg] = useState({ type: '', text: '' });

  const loadRentals = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API}/rentals`);
      const data = await res.json();
      setRentals(Array.isArray(data) ? data : data.rentals || []);
    } catch (error) {
      console.error('Error loading rentals:', error);
      setRentals([]);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    loadRentals();
  }, [loadRentals]);

  const handleReturnRental = async (rentalId) => {
    if (!window.confirm('Are you sure you want to mark this rental as returned?')) return;

    try {
      const res = await fetch(`${API}/rentals/return/${rentalId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' }
      });

      if (res.ok) {
        setMsg({ type: 'success', text: 'Rental returned successfully' });
        loadRentals();
      } else {
        const data = await res.json();
        setMsg({ type: 'error', text: data.message || 'Failed to return rental' });
      }
    } catch (error) {
      setMsg({ type: 'error', text: 'Error returning rental' });
    }
  };

  const handleDeleteRental = async (rentalId) => {
    if (!window.confirm('Are you sure you want to delete this rental record?')) return;

    try {
      const res = await fetch(`${API}/rentals/${rentalId}`, {
        method: 'DELETE'
      });

      if (res.ok) {
        setMsg({ type: 'success', text: 'Rental deleted successfully' });
        loadRentals();
      } else {
        const data = await res.json();
        setMsg({ type: 'error', text: data.message || 'Failed to delete rental' });
      }
    } catch (error) {
      setMsg({ type: 'error', text: 'Error deleting rental' });
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return '-';
    return new Date(dateString).toLocaleDateString();
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'ACTIVE': return '#FFA500';
      case 'ON TIME': return '#28A745';
      case 'LATE': return '#DC3545';
      default: return '#6C757D';
    }
  };

  const filteredRentals = rentals.filter(rental => {
    const matchesSearch = !search || 
      rental.UserName?.toLowerCase().includes(search.toLowerCase()) ||
      rental.GameTitle?.toLowerCase().includes(search.toLowerCase()) ||
      rental.CopyID?.toString().includes(search);

    const matchesFilter = filter === 'all' || 
      (filter === 'active' && rental.RentalStatus === 'ACTIVE') ||
      (filter === 'returned' && rental.RentalStatus !== 'ACTIVE') ||
      (filter === 'late' && rental.RentalStatus === 'LATE');

    return matchesSearch && matchesFilter;
  });

  const activeRentals = rentals.filter(r => r.RentalStatus === 'ACTIVE').length;
  const lateRentals = rentals.filter(r => r.RentalStatus === 'LATE').length;

  return (
    <div>
      <div className="page-header">
        <div>
          <div className="page-title">RENTAL MANAGEMENT</div>
          <div className="page-sub">{rentals.length} total rentals</div>
        </div>
        <div className="page-stats">
          <div className="stat">
            <div className="stat-number">{activeRentals}</div>
            <div className="stat-label">Active</div>
          </div>
          <div className="stat">
            <div className="stat-number" style={{ color: '#DC3545' }}>{lateRentals}</div>
            <div className="stat-label">Late</div>
          </div>
        </div>
      </div>

      {msg.text && (
        <div className={`alert alert-${msg.type}`} style={{ 
          padding: '10px', 
          margin: '10px 0', 
          borderRadius: '4px',
          backgroundColor: msg.type === 'success' ? '#D4EDDA' : '#F8D7DA',
          color: msg.type === 'success' ? '#155724' : '#721C24'
        }}>
          {msg.text}
        </div>
      )}

      <div className="controls" style={{ display: 'flex', gap: '10px', marginBottom: '20px', flexWrap: 'wrap' }}>
        <div className="search-bar" style={{ flex: 1, minWidth: '200px' }}>
          <input
            type="text"
            placeholder="Search by user name, game title, or copy ID..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ 
              width: '100%', 
              padding: '8px 12px', 
              border: '1px solid #ddd', 
              borderRadius: '4px',
              fontSize: '14px'
            }}
          />
        </div>
        <select
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{ 
            padding: '8px 12px', 
            border: '1px solid #ddd', 
            borderRadius: '4px',
            fontSize: '14px'
          }}
        >
          <option value="all">All Rentals</option>
          <option value="active">Active Only</option>
          <option value="returned">Returned</option>
          <option value="late">Late Returns</option>
        </select>
        <button
          onClick={loadRentals}
          style={{ 
            padding: '8px 16px', 
            backgroundColor: '#007BFF', 
            color: 'white', 
            border: 'none', 
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          🔄 Refresh
        </button>
      </div>

      {loading ? (
        <div style={{ textAlign: 'center', padding: '40px' }}>Loading rentals...</div>
      ) : filteredRentals.length === 0 ? (
        <div className="empty" style={{ textAlign: 'center', padding: '40px' }}>
          <div style={{ fontSize: '48px', marginBottom: '16px' }}>📋</div>
          <p>No rentals found</p>
        </div>
      ) : (
        <div className="rentals-table" style={{ overflowX: 'auto' }}>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px' }}>
            <thead>
              <tr style={{ backgroundColor: '#F8F9FA', borderBottom: '2px solid #DEE2E6' }}>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Rental ID</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>User Name</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Game Title</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Copy ID</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Platform</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Date Issued</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Due Date</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Date Returned</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Status</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Days Overdue</th>
                <th style={{ padding: '12px', textAlign: 'left', borderBottom: '1px solid #DEE2E6' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredRentals.map((rental) => (
                <tr key={rental.RentalID} style={{ borderBottom: '1px solid #DEE2E6', '&:hover': { backgroundColor: '#F8F9FA' } }}>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>#{rental.RentalID}</td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>
                    <div>
                      <strong>{rental.UserName}</strong>
                      {rental.UserEmail && (
                        <div style={{ fontSize: '12px', color: '#6C757D' }}>{rental.UserEmail}</div>
                      )}
                    </div>
                  </td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>
                    <div>
                      <strong>{rental.GameTitle}</strong>
                      {rental.Genre && (
                        <div style={{ fontSize: '12px', color: '#6C757D' }}>{rental.Genre}</div>
                      )}
                    </div>
                  </td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>
                    <span style={{ 
                      backgroundColor: '#E9ECEF', 
                      padding: '2px 8px', 
                      borderRadius: '12px', 
                      fontSize: '12px',
                      fontFamily: 'monospace'
                    }}>
                      {rental.CopyID}
                    </span>
                  </td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>{rental.Platform}</td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>{formatDate(rental.DateIssued)}</td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>
                    <div style={{ color: new Date(rental.DateDue) < new Date() && rental.RentalStatus === 'ACTIVE' ? '#DC3545' : 'inherit' }}>
                      {formatDate(rental.DateDue)}
                    </div>
                  </td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>
                    {rental.DateReturned ? formatDate(rental.DateReturned) : '-'}
                  </td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>
                    <span style={{ 
                      backgroundColor: getStatusColor(rental.RentalStatus),
                      color: 'white',
                      padding: '2px 8px',
                      borderRadius: '12px',
                      fontSize: '12px',
                      fontWeight: 'bold'
                    }}>
                      {rental.RentalStatus}
                    </span>
                  </td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>
                    {rental.DaysOverdue > 0 ? (
                      <span style={{ color: '#DC3545', fontWeight: 'bold' }}>
                        {rental.DaysOverdue} days
                      </span>
                    ) : (
                      '-'
                    )}
                  </td>
                  <td style={{ padding: '12px', borderBottom: '1px solid #DEE2E6' }}>
                    <div style={{ display: 'flex', gap: '5px' }}>
                      {rental.RentalStatus === 'ACTIVE' && (
                        <button
                          onClick={() => handleReturnRental(rental.RentalID)}
                          style={{
                            padding: '4px 8px',
                            backgroundColor: '#28A745',
                            color: 'white',
                            border: 'none',
                            borderRadius: '4px',
                            fontSize: '12px',
                            cursor: 'pointer'
                          }}
                        >
                          Return
                        </button>
                      )}
                      <button
                        onClick={() => handleDeleteRental(rental.RentalID)}
                        style={{
                          padding: '4px 8px',
                          backgroundColor: '#DC3545',
                          color: 'white',
                          border: 'none',
                          borderRadius: '4px',
                          fontSize: '12px',
                          cursor: 'pointer'
                        }}
                      >
                        Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
